{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "아파트 부설주차장 외부인 개방을 위한 차단기 설치 비용 지원 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시는 부설주차장의 소유자 또는 관리자가 주차장을 해당 시설물의 이용자 외에 일반의 이용에 제공하기 위하여 주차장의 이용에 필요한 시설물을 설치 또는 관리하고자 하는 때에는 그 소유자 또는 관리자에게 필요한 비용의 일부를 보조할 수 있다. 차단기 설치는 주차장 이용에 필요한 시설물 설치에 해당할 수 있으므로, 요건을 충족하면 비용 일부 보조 대상이 될 수 있다. 다만 보조 여부·금액·절차 등 구체적 사항은 시장이 정하도록 되어 있다.",
          "b_ids": "주차장:제24조제1항, 주차장:제24조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
